column81:
Lists are recursive, right. Better than double pointer indirection is to have the function return the new head. Note that the following code is not functional, but returning the new head makes it cleaner.<p><pre><code>    node *remove_if(node *head, remove_fn rm)
    {
        if (rm(head)) {
            return remove_if(head->next);
        }
        head->next = remove_if(head->next);
        return head;
     }
</code></pre>
A good use of this technique (returning pointers to the resulting node) is the following code which very cleanly implements AVL trees in C (from <a href="http://infoarena.ro/multe-smenuri-de-programare-in-cc-si-nu-numai" rel="nofollow">http://infoarena.ro/multe-smenuri-de-programare-in-cc-si-nu-...</a> -- scroll to the end (sorry, main article in Romanian)):<p><pre><code>    #define max(a, b) ((a) > (b) ? (a) : (b))
    #define geth(n) (n->h = 1 + max(n->l->h, n->r->h))

    struct node
    {
    int key, h;
    struct node *l, *r;
    } *R, *NIL;
    typedef struct node node;

    void init(void)
    {
    R = NIL = (node *) malloc(sizeof(node));
    NIL->key = NIL->h = 0,
    NIL->l = NIL->r = NULL;
    }

    node* rotleft(node *n)
    {
    node *t = n->l;

    n->l = t->r, t->r = n,
    geth(n), geth(t);
    return t;
    }

    node* rotright(node *n)
    {
    node *t = n->r;

    n->r = t->l, t->l = n,
    geth(n), geth(t);
    return t;
    }

    node* balance(node *n)
    {
    geth(n);
    if (n->l->h > n->r->h + 1)
    {
    if (n->l->r->h > n->l->l->h)
    n->l = rotright(n->l);
    n = rotleft(n);
    }
    else
    if (n->r->h > n->l->h + 1)
    {
    if (n->r->l->h > n->r->r->h)
    n->r = rotleft(n->r);
    n = rotright(n);
    }
    return n;
    }

    node* insert(node *n, int key)
    {
    if (n == NIL)
    {
    n = (node *) malloc(sizeof(node));
    n->key = key, n->h = 1, n->l = n->r = NIL;
    return n;
    }
    if (key < n->key)
    n->l = insert(n->l, key);
    else
    n->r = insert(n->r, key);
    return balance(n);
    }

    node* erase(node *n, int key)
    {
    node *t;
    if (n == NIL) return n;
    if (n->key == key)
    {
    if (n->l == NIL || n->r == NIL)
    {
    t = n->l == NIL ? n->r : n->l;
    free(n); return t;
    }
    else
    {
    for (t = n->r; t->l != NIL; t = t->l);
    n->key = t->key,
    n->r = erase(n->r, t->key);
    return balance(n);
    }
    }
    if (key < n->key)
    n->l = erase(n->l, key);
    else
    n->r = erase(n->r, key);
    return balance(n);
    }

    int search(node *n, int key)
    {
    if (n == NIL) return 0;
    if (n->key == key) return 1;
    if (key < n->key)
    return search(n->l, key);
    else
    return search(n->r, key);
    }</code></pre>

column121:
With one of my friends at the university we used to compete for a shorter/nicer implementation of each data structure in the algorithms class we were taking, and after using pointers-to-pointers in some previous cases (linked lists, binary search trees etc.) and each time ending up with an implementation I really liked, I tried to implement AVL trees[1] the same way, for example an AVL rotation would be done by a call like this:<p><pre><code>  avl_tree_rotate(avl, &t->left->right->left, &t->left->right, &t->left, t->left->right);
</code></pre>
Where avl_tree_rotate looked like this (avl_tree_update just recomputes the height after left or right branch height changes):<p><pre><code>  static void avl_tree_rotate(avl avl, V **from, V **to, V **parent, V *child) {
    if(*from) (*from)->parent = *to   ? (*to)->parent   : NULL;
    if(*to)   (*to)->parent   = *from ? (*from)->parent : NULL;
    avl_tree_swap(avl, from, to);
    child->parent = (*parent)->parent;
    if(!((*parent)->parent))
      avl->root = child;
    else if((*parent)->parent->left == *parent)
      (*parent)->parent->left = child;
    else if((*parent)->parent->right == *parent)
      (*parent)->parent->right = child;
    (*parent)->parent = child;
    *from = *parent;
    avl_tree_update(avl, *parent);
    avl_tree_update(avl, child);
  }
</code></pre>
It was one of nicer programming workouts I ever got (the whole class was a great experience and I think every professional programmer should go through implementing all the basic data structures and algorithms in plain C one time), but I never managed to get deletion right, despite spending quite some hours on it, it just went beyond my head. Not that it matters for linked lists, and in this case I made it deliberately harder on myself, but I think the moral of the story is that when you are too clever with implementation details, you might run out of your cleverness when starting to deal with the actual problem domain.<p>[1] <a href="http://en.wikipedia.org/wiki/AVL_tree" rel="nofollow">http://en.wikipedia.org/wiki/AVL_tree</a>
